import json

def find_filled_rows(grid, val, direction='both'):
    """Find all rows completely filled with a value"""
    rows = set()
    for r in range(len(grid)):
        if all(grid[r][c] == val for c in range(len(grid[0]))):
            rows.add(r)
    return rows

def find_filled_cols(grid, val):
    """Find all columns completely filled with a value"""
    cols = set()
    for c in range(len(grid[0])):
        if all(grid[r][c] == val for r in range(len(grid))):
            cols.add(c)
    return cols

def applies_rule(val):
    """Check if value forms a hollow rectangular shape"""
    grid = G['Demo pair 1 input']
    rows = find_filled_rows(grid, val)
    cols = find_filled_cols(grid, val)
    return len(rows) >= 2 and len(cols) >= 2

