def find_rectangular_shapes(grid):
    """Find all bounded rectangular shapes (hollow or filled)"""
    shapes = []
    rows, cols = len(grid), len(grid[0])
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] not in [8]:  # Skip background
                val = grid[r][c]
                # Find extent of this component
                min_r, max_r = r, r
                min_c, max_c = c, c

                # Expand in all directions while same value
                for dr in range(-1, 2):
                    for dc in range(-1, 2):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 < nr < rows and 0 < nc < cols and grid[nr][nc] == val:
                            min_r = min(min_r, nr)
                            max_r = max(max_r, nr)
                            min_c = min(min_c, nc)
                            max_c = max(max_c, nc)

                # Check if this is a hollow rectangle (border only, inside is background)
                is_square = True
                is_hollow = True

                # Check all positions in the bounding box
                for rr in range(min_r, max_r + 1):
                    for cc in range(min_c, max_c + 1):
                        if (rr == min_r or rr == max_r or cc == min_c or cc == max_c):
                            # Border position - should be val
                            if grid[rr][cc] != val:
                                is_hollow = False
                                is_square = False
                        else:
                            # Interior position - should be background (8)
                            if grid[rr][cc] != 8:
                                is_hollow = False
                if is_hollow:
                    shapes.append((val, (min_r, min_c, max_r, max_c)))
    return shapes

