def find_connected_regions(grid, value):
    """Find all connected regions of a given value"""
    visited = set()
    regions = []

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == value and (r, c) not in visited:
                # BFS to find connected region
                region = set()
                queue = deque([(r, c)])
                while queue:
                    cr, cc = queue.popleft()
                    if (cr, cc) in visited:
                        continue
                    if grid[cr][cc] != value:
                        continue
                    visited.add((cr, cc))
                    region.add((cr, cc))
                    for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if (nr, nc) not in visited:
                                queue.append((nr, nc))
                regions.append(region)
    return regions

